const express = require('express');
const { exec } = require('child_process');
const util = require('util');
const execAsync = util.promisify(exec);
const uploads = new Map();
const app = express();
app.use(express.json());

app.post('/upload/init', (req, res) => {
  const id = String(Date.now());
  uploads.set(id, { filename: req.body.filename });
  res.json({ id });
});

app.post('/upload/done/:id', async (req, res) => {
  const { filename } = uploads.get(req.params.id);
  await execAsync(`apprise "${process.env.APPRISE_URL}" -b "New file ${filename}"`);
  res.end();
});

const Koa = require('koa');
