const http = require('http');
const path = require('path');
const fs = require('fs');

const dir = path.normalize('/srv/files');

http.createServer((req, res) => {
  const fullPath = path.join(dir, decodeURIComponent(new URL(req.url, 'http://x').pathname));
  fs.stat(fullPath, (err, stat) => {
    if (!err && stat.isFile()) fs.createReadStream(fullPath).pipe(res);
  });
}).listen(8000);

const express = require('express');
const path = require('path');
const fs = require('fs');
const app = express();
const root = path.join(__dirname, 'tests/frontend');

app.get('/tests/frontend/*', (req, res) => {
  const subPath = req.url.substr('/tests/frontend'.length).split('?')[0];
  let filePath = path.normalize(root + '/');
  filePath += subPath.replace('..', '');
  fs.readFile(filePath, (err, content) => res.send(content));
});

import express from 'express';
import { Client } from 'pg';

const client = new Client();
const app = express();
app.use(express.json());

class Events {
  channel = 'tasks';
  async notify(payload: string) {
    await client.query(`NOTIFY ${this.channel}, '${payload}'`);
  }
}

app.post('/v1/immediate', async (req, res) => {
  await new Events().notify(req.body.group.key);
  res.json({ ok: true });
});

const express = require('express');
const fs = require('fs');
const app = express();

const countlyFs = {
  getStream(dest, cb) { cb(null, fs.createReadStream(dest)); },
};

app.get('/appimages/*', (req, res) => {
  countlyFs.getStream(__dirname + '/public/appimages/' + req.params[0], (err, stream) => {
    stream.pipe(res);
  });
});
